    "savings_debt_heading": {
      "type": "Text",
      "props": {
        "text": "Savings & Debt Repayment",
        "variant": "h3"
      },
      "children": []
    },
    "savings_debt_text_1": {
      "type": "Text",
      "props": {
        "text": "Emergency Fund: Aim for 3-6 months of essential expenses saved in a liquid account."
      },
      "children": []
    },
    "savings_debt_text_2": {
      "type": "Text",
      "props": {
        "text": "Retirement: Contributions to 401(k)s, IRAs, or other retirement accounts."
      },
      "children": []
    },
